def next_greater(values):
    answer = [None] * len(values)
    stack = []
    for i in range(len(values)):
        while len(stack) > 0 and values[stack[len(stack) - 1]] < values[i]:
            answer[stack.pop()] = i
        stack.append(i)
    return answer

