def previous_smaller(values):
    answer = []
    stack = []
    for i in range(len(values)):
        while len(stack) > 0 and values[stack[len(stack) - 1]] >= values[i]:
            stack.pop()
        if len(stack) == 0:
            answer.append(None)
        else:
            answer.append(stack[len(stack) - 1])
        stack.append(i)
    return answer

