def histogram_area(heights):
    for height in heights:
        if height < 0:
            return None
    best = 0
    stack = []
    for i in range(len(heights) + 1):
        current = 0
        if i < len(heights):
            current = heights[i]
        while len(stack) > 0 and heights[stack[len(stack) - 1]] >= current:
            height = heights[stack.pop()]
            left = 0
            if len(stack) > 0:
                left = stack[len(stack) - 1] + 1
            area = height * (i - left)
            if area > best:
                best = area
        if i < len(heights):
            stack.append(i)
    return best

