def ones_rectangle(rows):
    if len(rows) == 0:
        return 0
    width = len(rows[0])
    for row in rows:
        if len(row) != width:
            return None
        for value in row:
            if value != 0 and value != 1:
                return None
    heights = [0] * width
    best = 0
    for row in rows:
        for i in range(width):
            if row[i] == 0:
                heights[i] = 0
            else:
                heights[i] = heights[i] + 1
        area = histogram_area(heights)
        if area > best:
            best = area
    return best

